#include <stdio.h>

#define BUS_FARE 15          // macro: text swap before compiling

int main(void)
{
    const float PI = 3.14159f;  // const: a variable that cannot change
    float radius = 7.0f;

    float area = PI * radius * radius;
    printf("Area: %.2f\n", area);

    int trips = 4;
    printf("Bus cost: Rs %d\n", trips * BUS_FARE);

    return 0;
}

